package com.fuelflex.platform.operations.blocktwo;
import static org.assertj.core.api.Assertions.assertThat;import java.nio.file.*;import org.junit.jupiter.api.Test;
class TankReturnMigrationAndSecurityContractTest{
 @Test void v17DefinesDedicatedLedgerIdempotenceAndFinalFigures()throws Exception{String sql=Files.readString(Path.of("src/main/resources/db/migration/V17__add_tank_returns_and_operational_reconciliation.sql"));assertThat(sql).contains("CREATE TABLE tank_returns","CREATE TABLE tank_return_stock_movements","movement_type='TANK_RETURN'","UNIQUE(tank_return_id)","accounted_volume=ROUND(total_sold_volume+tank_return_volume,3)","expected_cash=cash_amount","expected_net_cash=ROUND(expected_cash-expense_amount,3)","tank-return:view","tank-return:create","r.code='MANAGER'","r.code='SUPERVISOR'").doesNotContain("ALTER TABLE fuel_sales");}
 @Test void managerCreatesAndBothWebRolesReadWithDedicatedPermissions()throws Exception{String source=Files.readString(Path.of("src/main/java/com/fuelflex/platform/operations/controller/DailyOperationsController.java"));assertThat(source).contains("@PostMapping(\"/manager/shift-assignments/{id}/tank-returns\")","hasAuthority('MANAGER') and hasAuthority('tank-return:create')","@GetMapping(\"/manager/operational-days/{id}/tank-returns\")","@GetMapping(\"/supervisor/operational-days/{id}/tank-returns\")","hasAuthority('SUPERVISOR') and hasAuthority('tank-return:view')");}
 @Test void v18AddsOneAuditableMeteredOutboundPerClosedShiftWithoutChangingV17()throws Exception{String sql=Files.readString(Path.of("src/main/resources/db/migration/V18__consolidate_metered_physical_stock.sql"));assertThat(sql).contains("CREATE TABLE metered_stock_movements","UNIQUE(shift_assignment_id)","movement_type='METERED_OUTBOUND'","CREATE TABLE tank_return_source_movements","TANK_RETURN_SOURCE_OUTBOUND","tank_id UUID NOT NULL").doesNotContain("ALTER TABLE fuel_sales");}
 @Test void v19PersistsFrozenCommercialClosureAndBackfillsFromV18AndHistoricalSales()throws Exception{String sql=Files.readString(Path.of("src/main/resources/db/migration/V19__persist_shift_commercial_closure.sql"));assertThat(sql).contains("source_tank_id","product_id","cash_unit_price","credit_unit_price","cash_amount","credit_amount","turnover","FROM metered_stock_movements","ALTER COLUMN source_tank_id SET NOT NULL","ck_shift_reconciliation_turnover","idx_shift_reconciliation_source_tank","idx_shift_reconciliation_product").doesNotContain("ALTER TABLE fuel_sales","CREATE TABLE fuel_sales");}
}
